css:
body :where([data-bz-node="nw"]) .bz-block{padding:0}
body :where([data-bz-node="nw"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="nw"]>.bz-container{padding-inline:0}

body [data-bz-node="nw"]{background:var(--paper);padding:104px 0 99px}
body [data-bz-node="nw"]>.bz-container{max-width:var(--container)}
body [data-bz-node="nw-head"] .bz-eyebrow{font:700 11px/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#6b6b6a;margin:0 0 6px;margin-bottom:8px}
body [data-bz-node="nw-head"] h2{font:700 42.4px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="nw-head-row"]{margin-bottom:57px}
body [data-bz-node^="nw-row-"]{display:grid;grid-template-columns:111px 1fr 220px;gap:0;align-items:center;border-top:1px solid #d2d2d0;padding:28px 0}
body [data-bz-node^="nw-row-"]:last-child{border-bottom:1px solid #d2d2d0}
body [data-bz-node^="nw-num-"],body [data-bz-node^="nw-body-"],body [data-bz-node^="nw-meta-"]{grid-column:auto}
body [data-bz-node^="nw-num-"] p{font:700 16px/1 var(--font-body);letter-spacing:.1em;color:var(--ink);margin:0}
body [data-bz-node^="nw-title-"] h3{font:700 19.1px/22px var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node^="nw-excerpt-"] .bz-text{max-width:625px;margin-top:10px}
body [data-bz-node^="nw-excerpt-"] p{font:400 12.5px/21.5px var(--font-body);color:#222;margin:0}
body [data-bz-node^="nw-meta-"]{text-align:right}
body [data-bz-node^="nw-date-"] p{font:400 12px/1 var(--font-body);letter-spacing:.03em;color:#555;margin:0}
body [data-bz-node^="nw-more-"]{margin-top:19px}
body [data-bz-node^="nw-more-"] .bz-btns{margin:0;justify-content:flex-end}
body [data-bz-node^="nw-more-"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;gap:9px;text-decoration:none}
body [data-bz-node^="nw-more-"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body [data-bz-node^="nw-more-"] .bz-btn:hover{color:var(--accent)}
@media (max-width:1100px){
  body [data-bz-node="nw"]{padding:72px 24px 56px}
  body [data-bz-node="nw-head"] h2{font-size:34px}
  body [data-bz-node^="nw-row-"]{grid-template-columns:64px 1fr;row-gap:16px}
  body [data-bz-node^="nw-meta-"]{grid-column:2;text-align:left;display:flex;align-items:center;gap:24px}
  body [data-bz-node^="nw-meta-"] .bz-btns{justify-content:flex-start}
  body [data-bz-node^="nw-date-"] p{margin:0}
  body [data-bz-node^="nw-more-"]{margin-top:0}
}
@media (max-width:640px){
  body [data-bz-node="nw"]{padding:56px 20px 40px}
  body [data-bz-node="nw-head"] h2{font-size:28px}
  body [data-bz-node="nw-head-row"]{margin-bottom:32px}
  body [data-bz-node^="nw-row-"]{grid-template-columns:40px 1fr}
  body [data-bz-node^="nw-title-"] h3{font-size:15px;line-height:20px}
  body [data-bz-node^="nw-meta-"]{flex-wrap:wrap;gap:10px 20px}
}
